import {dailyTaskFrame} from './daily-ui-art.mjs';
import {duelChosenSkill,duelSkillChoices,duelLoadout,DUEL_SKILL_KEYS} from './duel-skill-data.mjs';
import {skillArtStyle} from './skill-icons.mjs?v=20261030-duel12';
export function duelChoiceStyle(hero,skill){return skill?.column?`background-image:url('assets/campaign-growth/hero-${hero}-icons-v1.png');background-size:300% 100%;background-position:${skill.row*50}% 0%`:skillArtStyle(hero,skill?.key||'q');}
export function duelHotbarStyle(hero,key,loadout,recast=false){const s=duelChosenSkill(hero,key,loadout);return s?.column?duelChoiceStyle(hero,s):skillArtStyle(hero,key,recast);}
export function renderDuelSkillChoices(hero,value,baseSkills){const loadout=duelLoadout(hero,value);return DUEL_SKILL_KEYS.map((key,row)=>`<section class="duel-skill-row"><div class="duel-row-key"><kbd>${['F','E','R'][row]}</kbd><span>${['技艺','秘术','终式'][row]}</span></div><div class="duel-row-options">${duelSkillChoices(hero).filter(s=>s.row===row).map(s=>`<button type="button" class="duel-skill-choice" data-pick-skill="${s.id}" aria-pressed="${loadout[key]===s.id}" aria-label="${['F','E','R'][row]} 选择${s.name}">${dailyTaskFrame()}<i style="${duelChoiceStyle(hero,s)}"></i><span><small>${s.column?'衍生流派':'原生招式'} · ${(s.cd??baseSkills[key].cd).toFixed(1)}秒冷却</small><strong>${s.name}</strong><p>${s.description}</p></span><b aria-hidden="true">${loadout[key]===s.id?'◆':'◇'}</b></button>`).join('')}</div></section>`).join('');}
export function renderDuelSkillSlots(hero,value){return DUEL_SKILL_KEYS.map((key,row)=>{const s=duelChosenSkill(hero,key,value);return `<div class="duel-picked-slot"><kbd>${['F','E','R'][row]}</kbd><i style="${duelChoiceStyle(hero,s)}"></i><strong>${s.name}</strong></div>`;}).join('');}
